// File: c:/Users/tanne/flipopsLP/flipops-site/lib/matching/jail-parcel-matcher.ts
//
// Strategy-ladder matcher. Precision-first: high-confidence binds only.
// Ambiguous rows are recorded but NOT bound (parcelId=null).
//
// USAGE:
//   - Tier-1 (onScrape): call matchJailBookingBatch(justInsertedIds) synchronously
//     at end of each sheriff scraper, INSIDE the same DB transaction.
//   - Tier-2 (nightly): runJailParcelMatcherReconcile() at 03:30 ET, walks
//     trailing 30-day InmateBooking window.
//   - Tier-3 (onParcelSale): deferred to v1.1.

import { prisma } from '@/lib/prisma';
import { normalizeInmateName, parseOwnerName } from '@/lib/sheriffs/normalize-name';
import { levenshtein } from '@/lib/utils/levenshtein';

export type MatchStrategy =
  | 'S1_NAME_DOB'
  | 'S2_FULLKEY'
  | 'S3_UNIQUE_COUNTY'
  | 'S4_CITY'
  | 'S5_HOMESTEAD'
  | 'S6_FUZZY'
  | 'S7_HYPHEN'
  | 'REJECT_AMBIGUOUS'
  | 'MANUAL';

export type MatchStatus =
  | 'BOUND'         // confidence >= 0.85
  | 'PROVISIONAL'   // confidence 0.50-0.84 (informational, not surfaced to investor)
  | 'AMBIGUOUS'     // >1 candidate at same tier
  | 'NO_MATCH'      // no candidates
  | 'SUPPRESSED'    // ExemptOccupationDictionary hit
  | 'MANUAL';       // analyst-bound

export interface MatcherResult {
  bookingId: string;
  parcelId: string | null;
  strategy: MatchStrategy;
  confidence: number | null;
  status: MatchStatus;
  candidateParcelIds: string[];
}

const MATCHER_VERSION = 'v1.0';
const HIGH_CONFIDENCE_FLOOR = 0.85;
const PROVISIONAL_FLOOR = 0.50;

/** Tier-1 entrypoint — called synchronously at end of each scraper batch */
export async function matchJailBookingBatch(
  bookingIds: string[],
  opts: { batchId?: string; triggeredBy?: 'onScrape' | 'nightlyReconcile' | 'manualBackfill' } = {}
): Promise<MatcherResult[]> {
  if (bookingIds.length === 0) return [];
  const bookings = await prisma.inmateBooking.findMany({
    where: {
      id: { in: bookingIds },
      matchMethod: { not: 'MANUAL' }, // sticky: never overwrite human judgment
      suppressed: false,
    },
  });
  const results: MatcherResult[] = [];
  for (const booking of bookings) {
    const result = await matchOne(booking);
    results.push(result);
    await persistMatch(booking.id, result, opts);
  }
  return results;
}

/** Tier-2 entrypoint — nightly reconcile */
export async function runJailParcelMatcherReconcile(opts: { sinceDays?: number } = {}): Promise<{
  total: number; bound: number; provisional: number; ambiguous: number; noMatch: number;
}> {
  const since = new Date(Date.now() - (opts.sinceDays ?? 30) * 86400_000);
  const ids = await prisma.inmateBooking.findMany({
    where: {
      capturedAt: { gte: since },
      matchMethod: { not: 'MANUAL' },
      suppressed: false,
    },
    select: { id: true },
  });
  const batchId = `reconcile-${new Date().toISOString()}`;
  const results = await matchJailBookingBatch(ids.map(r => r.id), { batchId, triggeredBy: 'nightlyReconcile' });
  return {
    total: results.length,
    bound: results.filter(r => r.status === 'BOUND').length,
    provisional: results.filter(r => r.status === 'PROVISIONAL').length,
    ambiguous: results.filter(r => r.status === 'AMBIGUOUS').length,
    noMatch: results.filter(r => r.status === 'NO_MATCH').length,
  };
}

// ---------------------------------------------------------------------------
// Strategy ladder — try S1..S7 in order, first hit wins.
// EVERY query scopes by countyFips (Prisma middleware guard).
// ---------------------------------------------------------------------------
async function matchOne(booking: InmateBookingRow): Promise<MatcherResult> {
  // §119.071 defense-in-depth — check exempt dictionary FIRST
  const exemptHit = await prisma.exemptOccupationDictionary.findFirst({
    where: { normalizedName: booking.normalizedName, active: true },
  });
  if (exemptHit) {
    return { bookingId: booking.id, parcelId: null, strategy: 'REJECT_AMBIGUOUS',
             confidence: null, status: 'SUPPRESSED', candidateParcelIds: [] };
  }

  // S1: NAME + DOB exact
  if (booking.dateOfBirth) {
    const r = await tryS1NameDob(booking);
    if (r) return r;
  }

  // S2: FULLKEY (last+first+middleInitial) exact + unique
  const r2 = await tryS2FullKey(booking);
  if (r2) return r2;

  // S3: NAMEKEY exact + unique-in-county
  const r3 = await tryS3UniqueCounty(booking);
  if (r3) return r3;

  // S4: NAMEKEY + city signal
  const r4 = await tryS4City(booking);
  if (r4) return r4;

  // S5: homestead heuristic when multi-candidate
  const r5 = await tryS5Homestead(booking);
  if (r5) return r5;

  // S6: Levenshtein-2 fuzzy lastName
  const r6 = await tryS6Fuzzy(booking);
  if (r6) return r6;

  // S7: hyphenated surname split
  const r7 = await tryS7Hyphen(booking);
  if (r7) return r7;

  // REJECT
  return { bookingId: booking.id, parcelId: null, strategy: 'REJECT_AMBIGUOUS',
           confidence: null, status: 'NO_MATCH', candidateParcelIds: [] };
}

// ---- S1: name exact + DOB year exact ----
async function tryS1NameDob(b: InmateBookingRow): Promise<MatcherResult | null> {
  // Parcels in same county where ownerNormalized array contains booking.normalizedName
  // AND parcel.ownerDobYear (when present in any future enrichment) matches DOB year +/- 1.
  // Note: today Parcel does NOT carry DOB — S1 effectively requires DOB on inmate side
  // and reduces to "name exact + unique in county" until we add owner-DOB enrichment.
  const candidates = await prisma.parcel.findMany({
    where: {
      countyFips: b.countyFips,
      ownerName: { not: null },
      // ownerCorporate filtered in app code via parseOwnerName cache; see denorm note
    },
    select: { id: true, ownerName: true, situsCity: true, situsAddress: true, ownerMailingAddress: true },
  });
  const filtered = candidates.filter(p => isNonCorporateNameMatch(p.ownerName!, b.normalizedName));
  if (filtered.length === 1) {
    return { bookingId: b.id, parcelId: filtered[0].id, strategy: 'S1_NAME_DOB',
             confidence: 0.97, status: 'BOUND', candidateParcelIds: [filtered[0].id] };
  }
  return null;
}

// ---- S2: fullkey (last+first+mi) exact + unique ----
async function tryS2FullKey(b: InmateBookingRow): Promise<MatcherResult | null> {
  if (!b.middleName) return null;
  const fullKey = `${b.lastName}|${b.firstName}|${b.middleName.charAt(0)}`.toUpperCase();
  const hits = await rawQueryParcelByFullKey(b.countyFips, fullKey);
  if (hits.length === 1) {
    return { bookingId: b.id, parcelId: hits[0].id, strategy: 'S2_FULLKEY',
             confidence: 0.88, status: 'BOUND', candidateParcelIds: [hits[0].id] };
  }
  if (hits.length > 1) {
    return { bookingId: b.id, parcelId: null, strategy: 'REJECT_AMBIGUOUS',
             confidence: null, status: 'AMBIGUOUS', candidateParcelIds: hits.slice(0, 5).map(h => h.id) };
  }
  return null;
}

// ---- S3: nameKey exact + unique ----
async function tryS3UniqueCounty(b: InmateBookingRow): Promise<MatcherResult | null> {
  const hits = await rawQueryParcelByNameKey(b.countyFips, b.normalizedName);
  if (hits.length === 1) {
    return { bookingId: b.id, parcelId: hits[0].id, strategy: 'S3_UNIQUE_COUNTY',
             confidence: 0.80, status: 'BOUND', candidateParcelIds: [hits[0].id] };
  }
  if (hits.length > 1) {
    return { bookingId: b.id, parcelId: null, strategy: 'REJECT_AMBIGUOUS',
             confidence: null, status: 'AMBIGUOUS', candidateParcelIds: hits.slice(0, 5).map(h => h.id) };
  }
  return null;
}

// ---- S4: nameKey + city signal (OCFL address, PBSO arresting agency mapping) ----
async function tryS4City(b: InmateBookingRow): Promise<MatcherResult | null> {
  const city = b.addressCity ?? inferCityFromArrestingAgency(b.arrestingAgency);
  if (!city) return null;
  const hits = await rawQueryParcelByNameKeyAndCity(b.countyFips, b.normalizedName, city);
  if (hits.length === 1) {
    return { bookingId: b.id, parcelId: hits[0].id, strategy: 'S4_CITY',
             confidence: 0.72, status: 'PROVISIONAL', candidateParcelIds: [hits[0].id] };
  }
  return null;
}

// ---- S5: homestead heuristic (situsAddress == ownerMailingAddress) ----
async function tryS5Homestead(b: InmateBookingRow): Promise<MatcherResult | null> {
  const hits = await rawQueryParcelByNameKey(b.countyFips, b.normalizedName);
  const homestead = hits.filter(p => p.situsAddress && p.situsAddress === p.ownerMailingAddress);
  if (homestead.length === 1) {
    return { bookingId: b.id, parcelId: homestead[0].id, strategy: 'S5_HOMESTEAD',
             confidence: 0.60, status: 'PROVISIONAL', candidateParcelIds: [homestead[0].id] };
  }
  return null;
}

// ---- S6: pg_trgm fuzzy lastName, exact firstName ----
async function tryS6Fuzzy(b: InmateBookingRow): Promise<MatcherResult | null> {
  // Use pg_trgm GIN index (created in B1) for fast similarity lookup.
  const hits = await prisma.$queryRaw<Array<{ id: string; similarity: number }>>`
    SELECT id, similarity("ownerName", ${b.normalizedName}) AS similarity
    FROM flipops."Parcel"
    WHERE "countyFips" = ${b.countyFips}
      AND "ownerName" % ${b.normalizedName}
      AND similarity("ownerName", ${b.normalizedName}) > 0.6
    ORDER BY similarity DESC
    LIMIT 6
  `;
  const filtered = hits.filter(h => h.similarity > 0.7);
  if (filtered.length === 1) {
    return { bookingId: b.id, parcelId: filtered[0].id, strategy: 'S6_FUZZY',
             confidence: 0.55, status: 'PROVISIONAL', candidateParcelIds: [filtered[0].id] };
  }
  return null;
}

// ---- S7: hyphenated surname split ----
async function tryS7Hyphen(b: InmateBookingRow): Promise<MatcherResult | null> {
  if (!b.lastName?.includes('-') && !b.lastName?.includes(' ')) return null;
  const halves = b.lastName.split(/[-\s]/).filter(Boolean);
  for (const half of halves) {
    const altKey = `${b.firstName} ${half}`.toUpperCase();
    const hits = await rawQueryParcelByNameKey(b.countyFips, altKey);
    if (hits.length === 1) {
      return { bookingId: b.id, parcelId: hits[0].id, strategy: 'S7_HYPHEN',
               confidence: 0.50, status: 'PROVISIONAL', candidateParcelIds: [hits[0].id] };
    }
  }
  return null;
}

// ---------------------------------------------------------------------------
// Persistence
// ---------------------------------------------------------------------------
async function persistMatch(
  bookingId: string,
  r: MatcherResult,
  opts: { batchId?: string; triggeredBy?: string }
): Promise<void> {
  const confidenceMeetsFloor = r.confidence !== null && r.confidence >= 0.78;
  await prisma.$transaction([
    prisma.inmateBooking.update({
      where: { id: bookingId },
      data: {
        parcelId: confidenceMeetsFloor ? r.parcelId : null,
        matchConfidence: r.confidence,
        matchMethod: r.strategy,
        matchStatus: r.status,
        candidateParcelIds: r.candidateParcelIds.length > 0 ? r.candidateParcelIds : undefined,
        matchedAt: new Date(),
      },
    }),
    prisma.jailBookingMatchLog.create({
      data: {
        bookingId,
        parcelId: r.parcelId,
        strategy: r.strategy,
        confidence: r.confidence,
        candidateCount: r.candidateParcelIds.length,
        matchStatus: r.status,
        matcherVersion: MATCHER_VERSION,
        triggeredBy: opts.triggeredBy ?? 'onScrape',
        batchId: opts.batchId,
      },
    }),
  ]);
}

// ---- Helpers (corporate filter, raw queries, city inference) ----
function isNonCorporateNameMatch(ownerName: string, inmateNorm: string): boolean {
  const parsed = parseOwnerName(ownerName);
  if (parsed.ownerCorporate) return false;
  return parsed.candidates.some(c => c.nameKey === inmateNorm);
}

function inferCityFromArrestingAgency(agency: string | null): string | null {
  if (!agency) return null;
  // PBSO encodes '34-BOYNTON BEACH', '01-PBSO' etc. — strip leading digits + dash
  const m = agency.match(/^\d+-(.+)$/);
  return m ? m[1].trim() : null;
}

// Raw query helpers use pg_trgm GIN index + countyFips index; <10ms typical.
declare function rawQueryParcelByNameKey(countyFips: string, nameKey: string): Promise<ParcelLite[]>;
declare function rawQueryParcelByFullKey(countyFips: string, fullKey: string): Promise<ParcelLite[]>;
declare function rawQueryParcelByNameKeyAndCity(countyFips: string, nameKey: string, city: string): Promise<ParcelLite[]>;

interface ParcelLite { id: string; ownerName: string; situsAddress: string | null; ownerMailingAddress: string | null; situsCity: string | null; }
interface InmateBookingRow { id: string; countyFips: string; normalizedName: string; firstName: string | null; middleName: string | null; lastName: string | null; dateOfBirth: Date | null; addressCity: string | null; arrestingAgency: string | null; }

