export type JailDecayRegime = 'A_ACUTE' | 'B_FADE' | 'C_LONG' | 'D_TAIL' | 'E_FLOOR';

export function computeJailDecay(daysSinceEvent: number): number {
  if (daysSinceEvent < 0) return 1.0;                                    // future-dated (shouldn't happen)
  if (daysSinceEvent <= 7)  return 1.0;                                  // A: acute
  if (daysSinceEvent <= 60) return 1.0 - (daysSinceEvent - 7) * (0.5 / 53);  // B: 1.0 -> 0.5
  if (daysSinceEvent <= 365) return 0.5 - (daysSinceEvent - 60) * (0.4 / 305); // C: 0.5 -> 0.1
  if (daysSinceEvent <= 730) return 0.1 - (daysSinceEvent - 365) * (0.1 / 365); // D: 0.1 -> 0.0
  return 0;                                                              // E: floor (730+)
}

export function regimeForDays(daysSinceEvent: number): JailDecayRegime {
  if (daysSinceEvent <= 7) return 'A_ACUTE';
  if (daysSinceEvent <= 60) return 'B_FADE';
  if (daysSinceEvent <= 365) return 'C_LONG';
  if (daysSinceEvent <= 730) return 'D_TAIL';
  return 'E_FLOOR';
}

