schemaDesign.prismaModelCode:
// =============================================================================
// JAIL / INMATE BOOKINGS — freshness-layer signal
// =============================================================================
// One ROW per booking event (per individual, per incarceration). Backed by the
// 6 FL sheriff probes (JSO/HCSO/OCFL/BSO/MDCR/PBSO) but designed as the
// canonical superset so non-FL sheriffs can drop in without a schema change.
//
// SCHEMA NOTES:
// - Provenance pattern mirrors ParcelSale / Lien / RawSnapshot:
//   (source, capturedAt, legalRisk). Re-scrapes idempotent via @@unique.
// - Charges are NOT a separate table — stored as Json[] on this row. Rationale:
//   no row-level FK queries needed against charges (we filter by bondTotal /
//   highest-charge severity, both denormalized onto InmateBooking); avoids a
//   second table that would be 5-10x the row count of bookings.
// - Address fields nullable: only OCFL exposes street+city+zip; the other 5
//   sheriffs suppress per §119.071/Marsy's Law.
// - DOB nullable: HCSO + MDCR expose it; JSO/OCFL/BSO/PBSO suppress.
// - Mugshot stored as URL pointer to R2/S3 (jail-mugshots/{slug}/{bookingId}.jpg).
//   NEVER store base64 inline (OCFL ships ~66KB PNGs in the JSON; that bloats PG).
// - matcherState fields (parcelId, matchConfidence, matchMethod) are populated
//   by a SEPARATE matcher job, not the scraper. Scraper writes null; matcher
//   upserts. matchedAt indicates last matcher pass.
// - isExempt = true means the row HAS been flagged for §119.071 suppression
//   (LEO/judge/victim/sealed/expunged/juvenile). Most rows = false because all
//   6 sheriffs already pre-suppress at source. Field exists so we can flip a
//   row to exempt downstream (e.g. takedown request, internal occupation flag)
//   without deleting the audit trail.
// - releaseDate nullable. When null → still incarcerated as of capturedAt.
//   When set → released. release source: JSO ReleaseLog, OCFL re-poll absence,
//   PBSO release-date field, HCSO 90-day rule.
model InmateBooking {
  id                  String   @id @default(cuid())

  // -----------------------------------------------------------------
  // Source identity (sheriff + county)
  // -----------------------------------------------------------------
  sheriffSlug         String                       // "jso" | "hcso" | "ocfl" | "bso" | "mdcr" | "pbso"
  countyFips          String                       // "12031" | "12057" | "12095" | "12011" | "12086" | "12099"
  state               String                       // "FL"

  // -----------------------------------------------------------------
  // Booking identifiers — the source-of-truth ID varies by sheriff:
  //   JSO  → incarcerationId  (per-incarceration)
  //   HCSO → bookingNumber
  //   OCFL → bookingNumber    (e.g. "26018993" — year-prefixed)
  //   BSO  → jmsNumber        (JMS_NUMBER)
  //   MDCR → jailNumber       (e.g. "260137845")
  //   PBSO → bookingNumber    (e.g. "2026014341")
  // bookingId = the canonical per-booking source ID coerced to string.
  // externalBookingNo / inmateNumber / jacketNumber / obtsNumber / idsNumber /
  //   incarcerationId are kept as separate optional columns so multi-system
  //   joins (FDLE OBTS is statewide) are possible later.
  // -----------------------------------------------------------------
  bookingId           String                       // PK component — always set
  externalBookingNo   String?                      // raw sheriff booking number when different from bookingId
  incarcerationId    String?                      // JSO-only (per-incarceration counter)
  inmateNumber        String?                      // person-stable ID where exposed (JSO, MDCR IDS, PBSO jacket)
  jacketNumber        String?                      // PBSO "jacket number" (person-stable)
  obtsNumber          String?                      // statewide FDLE OBTS (PBSO exposes it; FL cross-county join key)
  idsNumber           String?                      // MDCR internal person ID

  // -----------------------------------------------------------------
  // Person identity
  // -----------------------------------------------------------------
  fullName            String                       // verbatim from source, trimmed
  firstName           String?
  middleName          String?
  lastName            String?
  suffix              String?                      // "JR", "SR", "III"...
  normalizedName      String                       // see normalizedNameSpec — uppercase, stripped, suffix-removed
  dateOfBirth         DateTime?                    // HCSO+MDCR only; null for JSO/OCFL/BSO/PBSO
  age                 Int?                         // OCFL BIRTH field (string of years); fallback when DOB suppressed
  race                String?                      // single-letter or word; raw verbatim
  gender              String?                      // "M" | "F" — normalized
  height              String?                      // "6' 1\"" — raw, free-text (foot-inch)
  weight              String?                      // "180 Lbs" — raw, free-text
  eyeColor            String?
  hairColor           String?

  // -----------------------------------------------------------------
  // Booking event
  // -----------------------------------------------------------------
  bookingDate         DateTime                     // local time normalized to UTC at parse; not null — always present in all 6 sources
  releaseDate         DateTime?                    // null = still in custody as of capturedAt
  bookingFacility     String?                      // "Main Detention Center" | "TGKCC" | "MWCC"...
  cellLocation        String?                      // PBSO Cell Location, MDCR Location, OCFL CELL
  arrestingAgency     String?                      // verbatim free-text ("01-PBSO", "ORANGE COUNTY SHERIFF OFFICE", "FHP TROOP L")
  arrestType          String?                      // JSO arrestType
  holdsForOtherAgencies Boolean?                   // PBSO "Holds For Other Agencies", OCFL HOLDS
  immigrationHold     Boolean?                     // OCFL HasImmigrationHold

  // -----------------------------------------------------------------
  // Charges + bond — denormalized for fast filtering, raw kept as JSON
  // -----------------------------------------------------------------
  charges             Json                         // ChargeRow[] — see Charge JSON shape in rationale
  chargeCount         Int      @default(0)         // denormalized len(charges) for histogram/filter
  topChargeStatute    String?                      // first/highest charge statute (e.g. "843.02", "784.041 2A")
  topChargeDesc       String?                      // first/highest charge description
  topChargeSeverity   String?                      // "FT" | "FF" | "FS" | "MF" | "MS" | "CT" | null — FL stat class code, see taxonomy

  totalBond           Int?                         // CENTS, summed across charges; null = unset/NO BOND across all charges
  highestSingleBond   Int?                         // CENTS, single max charge bond
  bondType            String?                      // normalized — see bondTypeTaxonomy. Across-charge winner if mixed.
  isNoBond            Boolean  @default(false)     // true if ALL charges return "NO BOND"

  courtDate           DateTime?                    // JSO nextCourtDate
  courtLocation       String?
  courtDepartment     String?

  // -----------------------------------------------------------------
  // Address (rare — OCFL only currently)
  // -----------------------------------------------------------------
  addressStreet       String?
  addressApt          String?
  addressCity         String?
  addressState        String?
  addressZip          String?                      // 5-digit; OCFL right-pads, parser MUST trim()

  // -----------------------------------------------------------------
  // Mugshot — stored in object storage, NOT inline
  // -----------------------------------------------------------------
  mugshotUrl          String?                      // public CDN URL or signed R2 URL
  mugshotStorageKey   String?                      // R2/S3 key: jail-mugshots/{sheriff}/{bookingId}.jpg
  mugshotCapturedAt   DateTime?                    // when we mirrored it (different from row capturedAt — fetched async)

  // -----------------------------------------------------------------
  // Matcher state — populated by matcher job, NOT scraper
  // -----------------------------------------------------------------
  parcelId            String?                      // FK-like to Parcel.id; not enforced FK so matcher can drop links freely
  matchConfidence     Float?                       // 0.0–1.0
  matchMethod         String?                      // "name+dob" | "name+city" | "name+address" | "name+obts" | "manual"
  matchedAt           DateTime?                    // last matcher pass that touched this row

  // -----------------------------------------------------------------
  // §119.071 exempt handling
  // -----------------------------------------------------------------
  // FALSE by default — all 6 sheriffs already pre-suppress §119.071-exempt rows
  // at source, so receiving a row implies it was source-cleared as public.
  // Flip to TRUE when:
  //  - Manual takedown request via support
  //  - Downstream occupation-filter detects LEO/judge/prosecutor/victim role
  //  - Sheriff later seals/expunges (detected on re-scrape returning 404 + retention rule)
  // When isExempt = true, the row is RETAINED for audit but MUST NOT be
  // surfaced in user-facing UI / API responses.
  isExempt            Boolean  @default(false)
  exemptReason        String?                      // "manual_takedown" | "occupation_filter" | "sealed" | "expunged" | "juvenile" | "victim"
  exemptAt            DateTime?

  // -----------------------------------------------------------------
  // Provenance (mirrors ParcelSale / RawSnapshot pattern)
  // -----------------------------------------------------------------
  source              String                       // "scraper:jso-bookings" | "scraper:ocfl-bestjail" | ...
  sourceTag           String?                      // canonical tag for cross-table join with RawSnapshot
  legalRisk           String   @default("yellow")  // "green" | "yellow" | "red" — all 6 are yellow per FL-COVERAGE-PLAN §5.1
  capturedAt          DateTime @default(now())     // when WE scraped this row
  lastSeenAt          DateTime @default(now())     // bumped on every re-scrape that re-confirms still-in-custody
  rawSnapshotId       String?                      // pointer back to RawSnapshot if full payload archived

  createdAt           DateTime @default(now())
  updatedAt           DateTime @updatedAt

  // -----------------------------------------------------------------
  // Indexes
  // -----------------------------------------------------------------
  // Idempotent re-scrape: (sheriffSlug, bookingId) is naturally unique across
  // all 6 sources. countyFips is denormalized but redundant with sheriff for now.
  @@unique([sheriffSlug, bookingId])

  // matcher hot-paths
  @@index([normalizedName, countyFips])             // name-based matcher join to Parcel.ownerName
  @@index([countyFips, bookingDate])                // "show me yesterday's Duval bookings"
  @@index([parcelId])                               // reverse lookup: parcel → recent bookings
  @@index([dateOfBirth])                            // matcher uses DOB band where available
  @@index([obtsNumber])                             // cross-county FL join (rare but powerful)

  // analytics / freshness
  @@index([sheriffSlug, capturedAt])
  @@index([releaseDate])                            // null = still in custody
  @@index([legalRisk])
  @@index([isExempt])
  @@index([bookingDate])
}

matcherDesign.confidenceThresholds:
{
  "BIND_AND_SURFACE_HIGH": ">=0.85 — write parcelId, matchConfidence, matchStrategy. Safe to surface in lead UI with 'Jail booking detected' badge. Acts as a +8 to +12 distress score contributor.",
  "BIND_LOW_CONFIDENCE": "0.50-0.84 — write parcelId, matchConfidence, matchStrategy, matchStatus='PROVISIONAL'. DO NOT surface in lead UI by default; surface only in a dedicated 'Possible matches — review' tray. Contributes +3 to distress score (capped). Owner-aimed comms (mail/SMS) MUST NOT use a provisional match.",
  "DO_NOT_BIND": "<0.50 — matchStatus='NO_MATCH' or 'AMBIGUOUS'. parcelId=null. The booking row still persists with the name + county + charges (counts toward county-level distress heatmap) but is not associated with any specific parcel.",
  "rationale": "Prompt explicitly states 'high PRECISION over high recall'. A wrongly-flagged owner letter is a brand-damaging event; a missed match is just a missed signal we can recover via skip-trace. Thresholds are intentionally conservative — we expect ~30-40% bind rate, not 80%."
}
